const DOG_DRAW_DURATION = 1800;
const DOG_STAGGER_STEP = 12;
const WORDMARK_START = 2650;
const WORDMARK_DURATION = 1300;
const FADE_START = 4600;
const FADE_DURATION = 650;
const EXIT_AT = 5350;

const ACCENT = 'hsl(var(--accent))';

const clamp01 = (value: number) => (value < 0 ? 0 : value > 1 ? 1 : value);
const smoothstep = (t: number) => {
  const x = clamp01(t);
  return x * x * (3 - 2 * x);
};
const easeOut = (t: number) => 1 - Math.pow(1 - clamp01(t), 2);

interface PageLoaderProps {
  error?: string | null;
  onRetry?: () => void;
  onFinished?: () => void;
}

function PageLoader({ error, onRetry, onFinished }: PageLoaderProps) {
  const containerRef = useRef<HTMLDivElement | null>(null);
  const hostRef = useRef<HTMLDivElement | null>(null);
  const elementsRef = useRef<{ dog: SVGPathElement[]; wordmark: SVGPathElement[] }>({
    dog: [],
    wordmark: [],
  });
  const lengthsRef = useRef<{ dog: number[]; wordmark: number[] }>({ dog: [], wordmark: [] });
  const startRef = useRef(0);
  const lastRef = useRef(0);
  const pausedRef = useRef(false);
  const rafRef = useRef<number>(0);
  const finishedRef = useRef(false);
  const onFinishedRef = useRef(onFinished);

  useEffect(() => {
    onFinishedRef.current = onFinished;
  });

  const finish = () => {
    cancelAnimationFrame(rafRef.current);
    rafRef.current = 0;
    if (finishedRef.current) return;
    finishedRef.current = true;
    onFinishedRef.current?.();
  };

  useEffect(() => {
    if (error) return;

    const container = containerRef.current;
    const host = hostRef.current;
    if (!container || !host) return;

    const dogEls = Array.from(host.querySelectorAll<SVGPathElement>('path[data-pl-kind="dog"]'));
    const wordmarkEls = Array.from(
      host.querySelectorAll<SVGPathElement>('path[data-pl-kind="wordmark"]'),
    );
    elementsRef.current = { dog: dogEls, wordmark: wordmarkEls };
    lengthsRef.current = { dog: dogEls.map((el) => el.getTotalLength()), wordmark: wordmarkEls.map((el) => el.getTotalLength()) };

    startRef.current = performance.now();
    lastRef.current = 0;
    finishedRef.current = false;

    const drawFinalState = () => {
      elementsRef.current.dog.forEach((el, i) => {
        const length = lengthsRef.current.dog[i];
        el.style.strokeDasharray = `${length} ${length}`;
        el.style.strokeDashoffset = '0';
        el.style.fill = ACCENT;
      });
      elementsRef.current.wordmark.forEach((el, i) => {
        const length = lengthsRef.current.wordmark[i];
        el.style.strokeDasharray = `${length} ${length}`;
        el.style.strokeDashoffset = '0';
        el.style.fill = ACCENT;
      });
      if (container) container.style.opacity = '1';
    };

    const tick = (timestamp: number) => {
      const elapsed = pausedRef.current ? lastRef.current : timestamp - startRef.current;
      lastRef.current = elapsed;

      let opacity = 1;
      if (elapsed >= FADE_START) {
        opacity = 1 - easeOut(clamp01((elapsed - FADE_START) / FADE_DURATION));
      }
      if (container) container.style.opacity = String(opacity);

      const t = elapsed;

      elementsRef.current.dog.forEach((el, i) => {
        const delay = i * DOG_STAGGER_STEP;
        const progress = smoothstep(clamp01((t - delay) / DOG_DRAW_DURATION));
        const length = lengthsRef.current.dog[i];
        el.style.strokeDasharray = `${length} ${length}`;
        el.style.strokeDashoffset = String(length * (1 - progress));
        el.style.fill = progress > 0.92 ? ACCENT : 'none';
      });

      elementsRef.current.wordmark.forEach((el, i) => {
        const start = WORDMARK_START + WORDMARK_GLYPHS[i].offset;
        const progress = smoothstep(clamp01((t - start) / WORDMARK_DURATION));
        const length = lengthsRef.current.wordmark[i];
        el.style.strokeDasharray = `${length} ${length}`;
        el.style.strokeDashoffset = String(length * (1 - progress));
        el.style.fill = progress > 0.92 ? ACCENT : 'none';
      });

      if (t < EXIT_AT) {
        rafRef.current = requestAnimationFrame(tick);
      } else {
        finish();
      }
    };

    if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
      drawFinalState();
      finish();
      return () => cancelAnimationFrame(rafRef.current);
    }

    rafRef.current = requestAnimationFrame(tick);

    return () => cancelAnimationFrame(rafRef.current);
  }, [error]);

  useEffect(() => {
    if (error) return;
    const container = containerRef.current;
    if (!container) return;

    const handleVisibility = () => {
      pausedRef.current = document.hidden;
    };

    document.addEventListener('visibilitychange', handleVisibility);

    const observer = new IntersectionObserver((entries) => {
      const entry = entries[0];
      pausedRef.current = !(entry?.isIntersecting ?? false);
    });
    observer.observe(container);

    return () => {
      document.removeEventListener('visibilitychange', handleVisibility);
      observer.disconnect();
    };
  }, [error]);

  if (error) {
    return (
      <div className="page-loader" role="alert" aria-live="polite" data-testid="page-load-error">
        <h1 className="serif">No pudimos cargar la carta</h1>
        <p>{error}</p>
        {onRetry && (
          <button type="button" className="text-cta focus-ring" onClick={onRetry}>
            Reintentar
          </button>
        )}
      </div>
    );
  }

  return (
    <div ref={containerRef} className="page-loader" role="status" aria-live="polite" data-testid="page-loading">
      <span className="sr-only">Cargando la carta de Cafés de Carla</span>
      <div ref={hostRef} className="page-loader-stage">
        <svg className="page-loader-svg page-loader-dog" viewBox="0 0 600 600" data-testid="preloader-dog" aria-hidden="true">
          <g transform="translate(0 600) scale(0.1 -0.1)">
            {DOG_PATHS.map((d, i) => (
              <path key={i} data-pl-kind="dog" data-pl-index={i} d={d} className="page-loader-path" />
            ))}
          </g>
        </svg>
        <svg className="page-loader-svg page-loader-wordmark" viewBox="0 0 2152.56 307.74" data-testid="preloader-wordmark" aria-hidden="true">
          <g transform="translate(-14.18 -7.96)">
            {WORDMARK_GLYPHS.map((glyph, i) => (
              <path key={i} data-pl-kind="wordmark" data-pl-index={i} d={glyph.d} className="page-loader-path" />
            ))}
          </g>
        </svg>
      </div>
    </div>
  );
}

export default PageLoader;
